"use client"
import React, { useEffect, useState } from "react"
import { supabase } from "../lib/supabase"
import type { Note } from "../types"

interface NotePosition {
  left: string
  top: string
  rotate: string
  delay: string
  zIndex: number
}

export const NoteWall: React.FC = () => {
  const [notes, setNotes] = useState<Note[]>([])
  const [loading, setLoading] = useState(true)
  const [positions, setPositions] = useState<Record<string, NotePosition>>({})

  useEffect(() => {
    if (!supabase) {
      setLoading(false)
      return
    }

    let isMounted = true

    const fetchNotes = async () => {
      const { data, error } = await supabase
        .from("notes")
        .select("*")
        .order("createdAt", { ascending: false })
        .limit(50)

      if (error) {
        console.error("Error fetching notes: ", error)
      } else if (data && isMounted) {
        const newNotes = data as Note[]
        setPositions((prevPositions) => {
          const newPositions = { ...prevPositions }
          let hasNewPositions = false
          newNotes.forEach((note) => {
            if (!newPositions[note.id!]) {
              newPositions[note.id!] = {
                left: `${5 + Math.random() * 75}%`,
                top: `${5 + Math.random() * 75}%`,
                rotate: `${-15 + Math.random() * 30}deg`,
                delay: `${Math.random() * -5}s`,
                zIndex: Math.floor(Math.random() * 50),
              }
              hasNewPositions = true
            }
          })
          return hasNewPositions ? newPositions : prevPositions
        })
        setNotes(newNotes)
      }
      if (isMounted) setLoading(false)
    }

    fetchNotes()

    const channel = supabase
      .channel("public:notes")
      .on(
        "postgres_changes",
        { event: "INSERT", schema: "public", table: "notes" },
        (payload) => {
          const newNote = payload.new as Note
          setNotes((prev) => [newNote, ...prev])
          setPositions((prevPositions) => {
            if (prevPositions[newNote.id!]) return prevPositions
            return {
              ...prevPositions,
              [newNote.id!]: {
                left: `${5 + Math.random() * 75}%`,
                top: `${5 + Math.random() * 75}%`,
                rotate: `${-15 + Math.random() * 30}deg`,
                delay: `${Math.random() * -5}s`,
                zIndex: Math.floor(Math.random() * 50) + 50,
              },
            }
          })
        }
      )
      .subscribe()

    return () => {
      isMounted = false
      supabase.removeChannel(channel)
    }
  }, [])

  if (loading) {
    const skeletonNotes = Array.from({ length: 6 }).map((_, i) => ({
      left: `${15 + ((i * 27) % 60)}%`,
      top: `${10 + ((i * 19) % 60)}%`,
      rotate: `${(i % 2 === 0 ? 1 : -1) * (5 + ((i * 3) % 15))}deg`,
      delay: `${-(i * 0.5)}s`,
    }))

    return (
      <div className="wall-container animate-fade-in">
        {skeletonNotes.map((pos, i) => (
          <div
            key={`skeleton-${i}`}
            className="note-card skeleton-note floating-note"
            style={
              {
                left: pos.left,
                top: pos.top,
                "--base-rotate": pos.rotate,
                animationDelay: pos.delay,
                zIndex: i,
              } as React.CSSProperties
            }
          >
            <div className="skeleton-line" style={{ width: "85%" }}></div>
            <div className="skeleton-line" style={{ width: "60%" }}></div>
            <div className="skeleton-line" style={{ width: "90%" }}></div>
            <div className="skeleton-line" style={{ width: "40%" }}></div>
            <div
              className="note-footer"
              style={{
                marginTop: "2rem",
                borderTop: "1px solid rgba(0,0,0,0.05)",
              }}
            >
              <div
                className="skeleton-line"
                style={{ width: "30%", marginBottom: 0, height: "0.9rem" }}
              ></div>
              <div
                className="skeleton-line"
                style={{ width: "20%", marginBottom: 0, height: "0.9rem" }}
              ></div>
            </div>
          </div>
        ))}
      </div>
    )
  }

  if (notes.length === 0) {
    return (
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          height: "100%",
          width: "100%",
          padding: "2rem",
          textAlign: "center",
        }}
      >
        <p
          style={{
            color: "#1e293b",
            fontWeight: 600,
            fontSize: "1.2rem",
            textShadow: "1px 1px 0px rgba(255,255,255,0.4)",
            background: "rgba(255, 255, 255, 0.4)",
            padding: "1rem 2rem",
            borderRadius: "8px",
          }}
        >
          Bức tường đang trống rỗng. Hãy là người đầu tiên dán ghi chú nhé!
        </p>
      </div>
    )
  }

  return (
    <div className="wall-container animate-fade-in">
      {notes.map((note) => {
        const pos = positions[note.id as string]
        if (!pos) return null

        return (
          <div
            key={note.id}
            className="note-card glass-panel floating-note"
            style={
              {
                backgroundColor: note.color?.startsWith("#")
                  ? note.color
                  : undefined,
                left: pos.left,
                top: pos.top,
                "--base-rotate": pos.rotate,
                animationDelay: pos.delay,
                zIndex: pos.zIndex,
              } as React.CSSProperties
            }
          >
            <div className="note-content">{note.content}</div>
            <div className="note-footer">
              <span className="note-author">- {note.author}</span>
              <span>
                {note.createdAt
                  ? new Date(note.createdAt).toLocaleDateString()
                  : "Just now"}
              </span>
            </div>
          </div>
        )
      })}
    </div>
  )
}
